public class PlotPanel:Panel {
 public double[] A,B; public string Caption="点击“计算预览”生成数据",Axis="样本序号 n"; public double XScale=1; public int First=0,Last=0; int hover=-1; float dpiScale=1; ToolTip tip=new ToolTip();
 public PlotPanel(){DoubleBuffered=true;BackColor=Color.White;Dock=DockStyle.Fill;MouseWheel+=Zoom;MouseDoubleClick+=delegate{Reset();};MouseMove+=MoveCursor;Resize+=delegate{Invalidate();};}
 public void Set(double[] a,double[] b,string caption,string axis,double scale){A=a;B=b;Caption=caption;Axis=axis;XScale=scale;Reset();}
 public void Reset(){First=0;Last=A==null?0:A.Length-1;Invalidate();}
 void Zoom(object sender,MouseEventArgs e){if(A==null||A.Length<3)return;int span=Last-First;double f=Math.Max(0,Math.Min(1,(e.X-65.0*dpiScale)/Math.Max(1,Width-90*dpiScale)));int center=First+(int)(span*f);int next=Math.Min(A.Length-1,Math.Max(2,(int)(span*(e.Delta>0?0.7:1.43))));First=Math.Max(0,Math.Min(A.Length-1-next,center-(int)(next*f)));Last=First+next;Invalidate();}
 void MoveCursor(object sender,MouseEventArgs e){if(A==null)return;int i=Math.Max(First,Math.Min(Last,First+(int)((e.X-65.0*dpiScale)/Math.Max(1,Width-90*dpiScale)*(Last-First))));if(i!=hover){hover=i;tip.SetToolTip(this,"n="+i+"  x="+Engine.F(i*XScale)+"\n原始="+Engine.F(A[i])+(B==null?"":"\n量化="+Engine.F(B[i])));}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;dpiScale=g.DpiX/96f;float d=dpiScale;g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;using(var title=new Font("Microsoft YaHei UI",10)){g.DrawString(Caption,title,Brushes.DarkSlateGray,new RectangleF(12*d,12*d,Width-24*d,42*d));}if(A==null||Last<=First)return;
  var rect=new RectangleF(65*d,65*d,Math.Max(10,Width-90*d),Math.Max(10,Height-125*d));double lo=double.PositiveInfinity,hi=double.NegativeInfinity;
  for(int i=First;i<=Last;i++){lo=Math.Min(lo,A[i]);hi=Math.Max(hi,A[i]);if(B!=null){lo=Math.Min(lo,B[i]);hi=Math.Max(hi,B[i]);}}
  if(Math.Abs(hi-lo)<1e-12){lo-=0.5;hi+=0.5;}double margin=(hi-lo)*0.07;lo-=margin;hi+=margin;
  using(var pen=new Pen(Color.FromArgb(220,230,237)))using(var font=new Font("Microsoft YaHei UI",9f)){
   for(int k=0;k<=4;k++){float y=rect.Top+rect.Height*k/4;g.DrawLine(pen,rect.Left,y,rect.Right,y);g.DrawString((hi-(hi-lo)*k/4).ToString("G4",Engine.CI),font,Brushes.DarkSlateGray,2*d,y-6*d);}
   for(int k=0;k<=4;k++){float x=rect.Left+rect.Width*k/4;g.DrawLine(pen,x,rect.Top,x,rect.Bottom);g.DrawString(((First+(Last-First)*k/4.0)*XScale).ToString("G5",Engine.CI),font,Brushes.DarkSlateGray,x-15*d,rect.Bottom+8*d);}
   g.DrawString(Axis+"  |  滚轮缩放 · 双击复位 · 悬停读数",font,Brushes.DarkSlateGray,rect.Left,rect.Bottom+32*d);
  }
  DrawSeries(g,rect,A,lo,hi,Color.FromArgb(18,119,151),2f*d);if(B!=null)DrawSeries(g,rect,B,lo,hi,Color.FromArgb(194,112,43),1f*d);
 }
 void DrawSeries(Graphics g,RectangleF rect,double[] data,double lo,double hi,Color color,float width){
  using(var pen=new Pen(color,width)){
   int count=Last-First+1,pixels=Math.Max(2,(int)rect.Width);
   if(count<=pixels*2){var p=new PointF[count];for(int j=0;j<count;j++)p[j]=new PointF(rect.Left+rect.Width*j/(count-1),rect.Bottom-(float)((data[First+j]-lo)/(hi-lo))*rect.Height);g.DrawLines(pen,p);}
   else { // Min/max per screen column preserves narrow peaks when rendering large tables.
    for(int px=0;px<pixels;px++){int from=First+(int)((long)px*count/pixels),to=First+(int)((long)(px+1)*count/pixels);double min=double.PositiveInfinity,max=double.NegativeInfinity;for(int j=from;j<to;j++){min=Math.Min(min,data[j]);max=Math.Max(max,data[j]);}float x=rect.Left+px;g.DrawLine(pen,x,rect.Bottom-(float)((min-lo)/(hi-lo))*rect.Height,x,rect.Bottom-(float)((max-lo)/(hi-lo))*rect.Height+0.5f);}
   }
  }
 }
}
