 void ShowRow(string key,bool show){rows[key].Visible=show;}
 void UpdateVisibility(){bool win=mode==0,activeWin=win||Key("add")!="None";ShowRow("window",win);ShowRow("wave",!win);ShowRow("add",!win);foreach(string k in new[]{"periodic","norm","gain"})ShowRow(k,activeWin);foreach(string k in new[]{"freqmode","fs","min","max","phase"})ShowRow(k,!win);ShowRow("cycles",!win&&Key("freqmode")=="false"&&Key("wave")!="DC");ShowRow("frequency",!win&&Key("freqmode")=="true"&&Key("wave")!="DC");ShowRow("duty",!win&&new[]{"Square","Pulse","Triangle"}.Contains(Key("wave")));string kind=win?Key("window"):Key("add");ShowRow("parameter",activeWin&&new[]{"Kaiser","Tukey","Gaussian"}.Contains(kind));labels["parameter"].Text=kind=="Kaiser"?"Kaiser β（0～50）":kind=="Tukey"?"Tukey α（0～1）":"Gaussian σ（样本数）";export.Text=Key("platform")=="Vivado"?"导出 COE":"导出 MIF";}
 void Changed(){if(loading||fields.Count<23||export==null)return;dirty=true;export.Enabled=csv.Enabled=false;generate.Enabled=save.Enabled=!busy;if(mode==2){export.Text="导出系数文件";export.Enabled=csv.Enabled=filterUI.Ready&&!busy;status.Text="滤波器：设置参数并计算，查看频率响应和量化稳定性。";return;}UpdateVisibility();if(result!=null){timePlot.Set(null,null,"参数已改变，请重新计算","样本序号",1);spectrumPlot.Set(null,null,"参数已改变，请重新计算","频率",1);grid.RowCount=0;filePreview.Clear();details.Clear();stats.Text="参数已改变；旧结果已隐藏，避免误导出。";}status.Text=mode==2?"滤波器功能预留，当前没有可导出的滤波器系数。":"设置完成后点击“计算预览”；只有与当前参数一致的结果才能导出。";try{var s=Read();double scale=Math.Pow(2,s.Fraction);if(s.Width<1||s.Width>32||s.Fraction<0||s.Fraction>32)throw new Exception();range.Text="可表示数值范围\r\n"+Engine.F(Engine.MinCode(s)/scale)+" ～\r\n"+Engine.F(Engine.MaxCode(s)/scale)+"\r\n量化步长："+Engine.F(1/scale);}catch{range.Text="请先填写有效位宽、小数位和数值参数。";}}
 void SetBusy(bool value){busy=value;left.Enabled=right.Enabled=!value;outputPath.Enabled=browse.Enabled=openFolder.Enabled=!value;foreach(var b in modes)b.Enabled=!value;reserved.Enabled=!value;generate.Enabled=save.Enabled=!value;load.Enabled=help.Enabled=!value;export.Enabled=csv.Enabled=!value&&(mode==2?filterUI.Ready:!dirty);}
 public async Task Calculate(){if(mode==2){try{SetBusy(true);status.Text="正在设计滤波器并检查量化稳定性…";await filterUI.Calculate();status.Text=filterUI.Ready?"滤波设计完成，请检查响应后导出。":"量化后不稳定，已阻止导出。";}catch(Exception ex){MessageBox.Show(this,ex.Message,"滤波设计失败");status.Text="滤波设计未完成。";}finally{SetBusy(false);}return;}try{var s=Read();Engine.Validate(s);SetBusy(true);status.Text="正在计算及检查量化范围…";var r=await Task.Run(()=>Engine.Generate(s));int size=0;var spec=await Task.Run(()=>Engine.Spectrum(r.Values,out size));Present(r,spec,size);}catch(Exception ex){dirty=true;status.Text="计算未完成："+ex.Message;MessageBox.Show(this,ex.Message,"参数检查",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{SetBusy(false);}}
 void Present(Result r,double[] spec,int size){result=r;generated=r.Config.Copy();spectrum=spec;fftLength=size;dirty=false;timePlot.Set(r.Values,r.Decoded.Take(r.Config.N).ToArray(),"蓝：原始数值  /  橙：量化后还原数值","样本序号 n",1);spectrumPlot.Set(spec,null,"原始序列 | FFT="+size+" | 20log10(|X|/max|X|), ≥ -160 dB",r.Config.Mode==0?"归一化频率（cycles/sample）":"频率（Hz）",(r.Config.Mode==0?1:r.Config.SampleRate)/size);grid.RowCount=r.Config.Depth;grid.Invalidate();filePreview.Text=Engine.Preview(r);details.Text="窗函数 / 波形 → 浮点数值 → 固定点量化 → W 位存储字。\r\n\r\n"+r.Notes+"\r\n\r\n频谱来自全部 N 个原始样本，补零至 FFT 长度，不作额外加窗；峰值归一化幅度谱，不是功率谱密度。零序列全部显示为 -160 dB（显示下限）。\r\n\r\nHEX / BIN / DEC 都表示存储位模式。有符号或偏移码须在 FPGA 端正确解释。";stats.Text="N="+r.Config.N+"  ·  深度="+r.Config.Depth+"  ·  位宽="+r.Config.Width+"  ·  数据载荷="+((long)r.Config.Depth*r.Config.Width+7)/8+" B\r\n实际最小 / 最大："+r.Min.ToString("G6")+" / "+r.Max.ToString("G6")+"\r\n最大量化误差："+r.MaxError.ToString("G5")+"   RMS 误差："+r.RmsError.ToString("G5")+"   饱和："+r.Saturated+" 点";status.Text="计算完成。"+(r.Saturated>0?"发生饱和，导出时将再次提示。":"数据未溢出，可以导出。");export.Enabled=csv.Enabled=true;}
 void GridValue(object sender,DataGridViewCellValueEventArgs e){if(result==null||dirty||e.RowIndex>=result.Words.Length)return;int i=e.RowIndex;switch(e.ColumnIndex){case 0:e.Value=i;break;case 1:e.Value=i<result.Values.Length?Engine.F(result.Values[i]):"0（补零）";break;case 2:e.Value=Engine.F(result.Decoded[i]);break;case 3:e.Value=result.Integers[i];break;case 4:e.Value=Engine.Word(result.Words[i],16,result.Config.Width);break;}}
 bool ExportReady(){if(dirty||result==null){MessageBox.Show(this,"请先重新计算预览。");return false;}return result.Saturated==0||MessageBox.Show(this,"有 "+result.Saturated+" 个点发生饱和，生成数据已不同于原始数值。确认导出吗？","确认饱和结果",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes;}
 string ResolveOutputDirectory(bool create){string raw=outputPath.Text.Trim().Trim('"');if(string.IsNullOrWhiteSpace(raw)||!Path.IsPathRooted(raw))throw new ArgumentException("保存位置请输入完整目录，例如 D:\\FPGA\\generated。");string dir=Path.GetFullPath(raw);if(create)Directory.CreateDirectory(dir);return dir;}
 string PrepareOutput(){try{return ResolveOutputDirectory(true);}catch(Exception ex){MessageBox.Show(this,ex.Message,"保存位置无效");return null;}}
 void RememberDirectory(string directory){outputDir=directory;outputPath.Text=directory;try{File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"output-location.txt"),directory);}catch{/* Export remains successful if portable folder is read-only. */}}
 async void ExportMemory(){if(mode==2){filterUI.Export("memory");return;}if(!ExportReady())return;string dir=PrepareOutput();if(dir==null)return;string ext=result.Config.Platform=="Vivado"?"coe":"mif";using(var dialog=new SaveFileDialog{Filter=ext.ToUpper()+" 文件|*."+ext,DefaultExt=ext,AddExtension=true,InitialDirectory=dir,FileName=(mode==0?result.Config.Window:result.Config.Wave)+"_N"+result.Config.N+"_W"+result.Config.Width+"."+ext,OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;if(!string.Equals(Path.GetExtension(dialog.FileName),"."+ext,StringComparison.OrdinalIgnoreCase)){MessageBox.Show(this,"请使用 ."+ext+" 扩展名。");return;}try{SetBusy(true);await Task.Run(()=>Engine.Export(dialog.FileName,result));RememberDirectory(Path.GetDirectoryName(dialog.FileName));status.Text="已导出并逐点回读验证："+dialog.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"导出失败");}finally{SetBusy(false);}}}
 async void ExportCsv(){if(mode==2){filterUI.Export("coeff");return;}if(!ExportReady())return;string dir=PrepareOutput();if(dir==null)return;using(var dialog=new SaveFileDialog{Filter="CSV 数据|*.csv",DefaultExt="csv",InitialDirectory=dir,FileName="signal_data.csv",OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{SetBusy(true);await Task.Run(()=>Engine.ExportCsv(dialog.FileName,result));RememberDirectory(Path.GetDirectoryName(dialog.FileName));status.Text="CSV 已导出："+dialog.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"导出失败");}finally{SetBusy(false);}}}
 void SaveSettings(){if(mode==2){filterUI.Save();return;}try{var s=Read();Engine.Validate(s);string dir=PrepareOutput();if(dir==null)return;using(var d=new SaveFileDialog{Filter="参数方案 XML|*.xml",DefaultExt="xml",InitialDirectory=dir,FileName="signal_settings.xml"})if(d.ShowDialog(this)==DialogResult.OK){s.Save(d.FileName);RememberDirectory(Path.GetDirectoryName(d.FileName));status.Text="参数已保存："+d.FileName;}}catch(Exception ex){MessageBox.Show(this,ex.Message,"参数检查");}}
 void LoadSettings(){if(mode==2){filterUI.LoadParameters();return;}using(var d=new OpenFileDialog{Filter="参数方案 XML|*.xml",InitialDirectory=Directory.Exists(outputPath.Text)?outputPath.Text:outputDir})if(d.ShowDialog(this)==DialogResult.OK)try{var s=Settings.Load(d.FileName);Engine.Validate(s);Apply(s);status.Text="参数已载入，请计算预览。";}catch(Exception ex){MessageBox.Show(this,ex.Message,"载入失败");}}
 void ShowHelp(){string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"docs","使用说明.txt");string content=File.Exists(file)?File.ReadAllText(file):"请参阅随附 docs 文件夹。\r\n\r\n输入数值 x，以 q=round(x*2^F) 量化。\r\n有符号范围 [-2^(W-1), 2^(W-1)-1]。\r\nCOE 用于 Vivado ROM/RAM 初始化，不是滤波器 IP 系数文件。";using(var f=new Form{Text="使用与公式说明",Size=new Size(900,720),StartPosition=FormStartPosition.CenterParent}){f.Controls.Add(new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text=content,Font=new Font(Font.FontFamily,11),BackColor=Color.White});f.ShowDialog(this);}}
 public void Render(string directory){Directory.CreateDirectory(directory);Show();Application.DoEvents();for(int i=0;i<3;i++){SwitchMode(i);if(i<2){var s=Read();var r=Engine.Generate(s);int n;var spec=Engine.Spectrum(r.Values,out n);Present(r,spec,n);}Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(directory,"screen_"+i+".png"));}}Close();}
 public string UiTest(){Apply(new Settings());var r=Engine.Generate(Read());int n;Present(r,Engine.Spectrum(r.Values,out n),n);if(!export.Enabled)throw new Exception("UI export not enabled");Set("gain","0.5");if(export.Enabled||!dirty||grid.RowCount!=0)throw new Exception("UI stale export guard failed");SwitchMode(2);if(!generate.Enabled||export.Enabled)throw new Exception("UI filter initial gating failed");Filters.Validate(filterUI.Read());var ft=filterUI.Calculate();while(!ft.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(5);}ft.GetAwaiter().GetResult();if(!filterUI.Ready||!export.Enabled)throw new Exception("FIR UI generation failed");filterUI.Apply(new FilterSettings{Structure="IIR",Order=4,Format="ROM COE"});if(export.Enabled||filterUI.Ready)throw new Exception("Filter stale result guard failed");ft=filterUI.Calculate();while(!ft.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(5);}ft.GetAwaiter().GetResult();if(!filterUI.Ready||filterUI.Result.Sos==null)throw new Exception("IIR UI generation failed");Apply(new Settings{Mode=1,Wave="Square",Duty=0.25});if(Read().Wave!="Square"||!rows["duty"].Visible)throw new Exception("UI parameter roundtrip failed");string original=outputPath.Text;outputPath.Text="relative-folder";bool rejected=false;try{ResolveOutputDirectory(false);}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("Relative output path accepted");string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","results","中文目录 空格");outputPath.Text=dir;Engine.Export(Path.Combine(ResolveOutputDirectory(true),"ui_export.coe"),r);RememberDirectory(dir);if(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"output-location.txt"))!=dir)throw new Exception("Directory persistence failed");RememberDirectory(original);Application.DoEvents();if(left.HorizontalScroll.Visible||right.HorizontalScroll.Visible)throw new Exception("Unwanted horizontal scrollbar: left="+left.ClientSize+" padding="+left.Padding+" max="+left.Controls.Cast<Control>().Max(c=>c.Right+c.Margin.Right)+"; right="+right.ClientSize+" padding="+right.Padding+" max="+right.Controls.Cast<Control>().Max(c=>c.Right+c.Margin.Right));using(var g=CreateGraphics()){return "PASS: UI stale-result invalidation, export gating, filter page initial gating, parameter roundtrip, output path validation, Unicode path export, saved directory preference\r\nGraphics DPI="+g.DpiX+"; Form="+Width+"x"+Height+"; Font="+Font.SizeInPoints+" pt; horizontal scrollbars=none";}}
}
